package ru.hive13.server;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.util.*;
import java.nio.file.*;

class ObjectMechanicsTest {
    @Test void legacyAnalysisCommandKeepsItsAutomaticApproach(){var e=engine();e.state.flags.add("sample_goal");e.state.rooms.get("B7").powered=true;e.state.doors.get("D16").status=DoorStatus.OPEN;e.state.actor(1).inventory.put("hive_sample",new Item("hive_sample","Образец",1,.4));var result=cmd(e,1,"INTERACT",Map.of("target","B7","action","SAMPLE"));assertTrue(result.accepted(),result.reason());assertEquals(1,e.state.actor(1).queue.size());e.advance(35);assertTrue(e.state.flags.contains("hive_core_studied"));assertEquals(0,e.state.actor(1).inventory.get("hive_sample").count);}
    @Test void rejectedObjectOrMoveCannotEraseAnAlreadyAcceptedOperation(){var e=engine();use(e,0,"switchboard","REPAIR");assertEquals(1,e.state.actor(0).queue.size());e.state.doors.get("D19").status=DoorStatus.CLOSED;assertFalse(cmd(e,0,"USE_OBJECT",Map.of("target","store","action","LOOT")).accepted());assertEquals(1,e.state.actor(0).queue.size());assertFalse(cmd(e,0,"MOVE",Map.of("x",9000,"y",9000,"mode","WALK")).accepted());assertEquals(1,e.state.actor(0).queue.size());e.advance(30);assertTrue(e.state.flags.contains("power_stable"));assertEquals(10,e.state.supplies.get("parts"));}
    @Test void successfulQuarantineCannotTriggerDirtyAdmissionWarning(){var e=engine();var lina=e.state.npcs.get("lina");lina.condition="QUARANTINE";lina.location="B5";e.state.flags.addAll(List.of("lina_safe","hive_core_studied","lina_decided"));e.state.cycle=4;place(e,1,"isolation");use(e,1,"isolation","RESCUE");e.advance(6.1);assertEquals("ALLY",lina.condition);assertTrue(e.state.flags.contains("lina_saved"));assertTrue(e.state.events.stream().noneMatch(event->event.text.contains("На одежде Лины сохранились споры")));}
    @Test void generatorAndFilterAreRealPhysicalOperations(){var e=engine();place(e,0,"generator");use(e,0,"generator","GENERATOR");e.advance(6.1);assertEquals(68,e.state.power);assertEquals(5,e.state.supplies.get("fuel"));assertFalse(cmd(e,0,"USE_OBJECT",Map.of("target","generator","action","GENERATOR")).accepted());place(e,0,"filter");use(e,0,"filter","FILTER");e.advance(6.1);assertEquals(81,e.state.ventilation);assertEquals(5,e.state.supplies.get("filters"));}
    @Test void burningOccupiedQuarantineKillsNpcAndBlocksRescue(){var e=engine();e.state.flags.addAll(List.of("hive_core_studied","lina_decided","lina_safe","power_stable"));var lina=e.state.npcs.get("lina");lina.condition="QUARANTINE";lina.location="B5";vote(e,"burn_hive");assertEquals("DEAD",lina.condition);assertTrue(e.state.flags.contains("lina_lost"));e.state.cycle=4;e.advance(.1);assertTrue(e.state.events.stream().noneMatch(event->event.text.contains("У меня пропуск станции 47")));place(e,1,"isolation");assertFalse(cmd(e,1,"USE_OBJECT",Map.of("target","isolation","action","RESCUE")).accepted());}
    private GameEngine engine(){var e=new GameEngine(WorldFactory.create("STORY"));e.state.creatures.clear();for(var a:e.state.actors){a.connected=true;a.ready=true;}e.start();return e;}
    private GameEngine.Result cmd(GameEngine e,int slot,String type,Object data){return e.command(slot,new Packet(type,UUID.randomUUID().toString(),data));}
    private void place(GameEngine e,int slot,String id){var f=WorldObjects.get(id);var a=e.state.actor(slot);a.roomId=f.room();a.x=f.x();a.y=f.y();}
    private void use(GameEngine e,int slot,String id,String action){var r=cmd(e,slot,"USE_OBJECT",Map.of("target",id,"action",action));assertTrue(r.accepted(),r.reason());}
    private void vote(GameEngine e,String id){e.state.phase=Phase.VOTING;e.prepareOptions();for(int i=0;i<3;i++){var r=cmd(e,i,"VOTE",Map.of("cycle",e.state.cycle,"option",id));assertTrue(r.accepted(),r.reason());}}
    @Test void allPhysicalObjectsOccupyWalkableFloor(){var e=engine();for(var f:WorldObjects.all()){assertTrue(e.state.rooms.get(f.room()).contains(f.x(),f.y()),f.id());assertFalse(f.actions().isEmpty());}}
    @Test void approachAndRepairUseRealPathAndTime(){var e=engine();var a=e.state.actor(0);use(e,0,"switchboard","REPAIR");assertEquals(225,a.x);assertFalse(a.path.isEmpty());assertFalse(a.queue.isEmpty());assertEquals(12,e.state.supplies.get("parts"));e.advance(30);assertTrue(e.state.flags.contains("power_stable"));assertEquals("B2",a.roomId);assertEquals(10,e.state.supplies.get("parts"));assertEquals(85,e.state.power);}
    @Test void cancelledRepairResumesWithoutPrematureOrDuplicateCost(){var e=engine();place(e,0,"switchboard");use(e,0,"switchboard","REPAIR");e.advance(5);cmd(e,0,"STOP",Map.of());assertEquals(12,e.state.supplies.get("parts"));use(e,0,"switchboard","REPAIR");assertEquals(5,e.state.actor(0).taskProgress,.01);e.advance(7.1);assertEquals(10,e.state.supplies.get("parts"));assertFalse(cmd(e,0,"USE_OBJECT",Map.of("target","switchboard","action","REPAIR")).accepted());}
    @Test void twoPeopleCannotLootTheSameCabinetTwice(){var e=engine();place(e,0,"store");place(e,1,"store");use(e,0,"store","LOOT");use(e,1,"store","LOOT");e.advance(6.1);assertEquals(16,e.state.supplies.get("parts"));assertEquals(8,e.state.supplies.get("filters"));}
    @Test void sampleVotePowersLabAndEnablesRealInventoryResearch(){var e=engine();assertFalse(e.state.rooms.get("B7").powered);vote(e,"sample_goal");assertEquals(5,e.state.supplies.get("batteries"));assertTrue(e.state.rooms.get("B7").powered);assertFalse(e.state.flags.contains("hive_core_studied"));assertTrue(e.state.options.stream().noneMatch(o->o.id.equals("sample_goal")));place(e,1,"sample");use(e,1,"sample","COLLECT");e.advance(6.1);assertEquals(1,e.state.actor(1).inventory.get("hive_sample").count);use(e,1,"sample","ANALYSE");e.advance(10.1);assertEquals(0,e.state.actor(1).inventory.get("hive_sample").count);assertTrue(e.state.sharedEvidence.contains("water_report"));e.state.flags.add("lina_decided");e.prepareOptions();assertTrue(e.state.options.stream().anyMatch(o->o.id.equals("biofilter")));assertTrue(e.state.options.stream().anyMatch(o->o.id.equals("burn_hive")));}
    @Test void bioresearchDecisionsHaveDifferentPersistentPhysicalEffects(){var bio=engine();bio.state.flags.addAll(List.of("hive_core_studied","lina_decided","power_stable"));bio.state.power=85;vote(bio,"biofilter");assertEquals(95,bio.state.water,.001);assertEquals(4,bio.state.supplies.get("filters"));bio.advance(10);assertTrue(bio.state.water>95);var burn=engine();burn.state.flags.addAll(List.of("hive_core_studied","lina_decided","power_stable"));burn.state.power=85;vote(burn,"burn_hive");assertEquals(55,burn.state.water);assertEquals(0,burn.state.rooms.get("B4").biomass);assertEquals(4,burn.state.supplies.get("fuel"));assertNotEquals(bio.state.flags,burn.state.flags);}
    @Test void openingDoorAloneDoesNotEvacuateButLiftActuallyDoes(){var e=engine();e.state.actor(2).life="DORMANT";e.state.flags.add("archive_access");e.state.doors.get("D13").status=DoorStatus.OPEN;place(e,0,"exit");place(e,1,"exit");assertFalse(e.state.flags.contains("surface_goal"));assertFalse(cmd(e,0,"USE_OBJECT",Map.of("target","exit","action","ASCEND")).accepted());use(e,0,"exit","PRESSURIZE");e.advance(8.1);assertTrue(e.state.flags.contains("exit_ready"));use(e,0,"exit","ASCEND");e.advance(4.1);assertEquals("EVACUATED",e.state.actor(0).life);assertEquals(Phase.ACTION,e.state.phase);use(e,1,"exit","ASCEND");e.advance(4.1);assertEquals(Phase.GAME_OVER,e.state.phase);assertTrue(e.state.ending.contains("Выход"));assertEquals(6,e.state.epilogue.size());}
    @Test void hostCanBeMedicAndOtherCharactersCannotStartSession(){var s=WorldFactory.create("STORY");s.hostSlot=1;var e=new GameEngine(s);for(var a:s.actors){a.connected=true;a.ready=true;}assertFalse(cmd(e,0,"START",Map.of()).accepted());assertTrue(cmd(e,1,"SESSION",Map.of("players",2)).accepted());assertTrue(cmd(e,1,"START",Map.of()).accepted());}
    @Test void fullBackpackCannotConsumeMedCabinetStock(){var e=engine();place(e,0,"medcab");e.state.actor(0).inventory.put("ballast",new Item("ballast","Груз",1,17));assertFalse(cmd(e,0,"USE_OBJECT",Map.of("target","medcab","action","MEDKIT")).accepted());assertEquals(6,e.state.supplies.get("meds"));}
    @Test void objectProgressAndConsequencesSurviveSave(@TempDir Path dir)throws Exception{var e=engine();place(e,0,"switchboard");use(e,0,"switchboard","REPAIR");e.advance(5);var file=dir.resolve("objects.json");SaveStore.save(file,e.state);var loaded=new GameEngine(SaveStore.load(file));loaded.advance(7.1);assertTrue(loaded.state.flags.contains("power_stable"));assertEquals(10,loaded.state.supplies.get("parts"));assertEquals(0,loaded.state.hostSlot);}
}
